// Now add our panels.
const idents = MailServices.accounts.getIdentitiesForServer(server);
if (idents.length) {
  panels.push(
    { string: getString("prefPanel-server"), src: "am-server.xhtml" },
    { string: getString("prefPanel-copies"), src: "am-copies.xhtml" },
    {
      string: getString("prefPanel-addressing"),
      src: "am-addressing.xhtml",
    }
  );
}

// Everyone except News, RSS and IM has a junk panel
// XXX: unextensible!
// The existence of server.spamSettings can't currently be used for this.
if (
  server.type != "nntp" &&
  server.type != "rss" &&
  server.type != "im"
) {
  panels.push({
    string: await document.l10n.formatValue("panel-manage-spam"),
    src: "am-junk.xhtml",
  });
}

// Add the synchronization/diskspace panel?
if (server.type != "im") {
  // EWS looks like a special case here, but really it's just that
  // the meaning of .offlineSupportLevel is pretty confused.
  // Ongoing investigation and notes in Bug 1992042.
  const isSync =
    server.offlineSupportLevel >= 10 || server.type == "ews";
  const title = getString(
    isSync ? "prefPanel-synchronization" : "prefPanel-diskspace"
  );
  panels.push({ string: title, src: "am-offline.xhtml" });
}
